CREATE TABLE auto_buy_budgets (
 owner_id TEXT NOT NULL,id TEXT NOT NULL,project_id TEXT NOT NULL,project_revision INTEGER NOT NULL,
 document TEXT NOT NULL CHECK(json_valid(document) AND length(CAST(document AS BLOB))<=65536),document_sha256 TEXT NOT NULL,
 maximum_input_lamports INTEGER NOT NULL CHECK(typeof(maximum_input_lamports)='integer' AND maximum_input_lamports BETWEEN 1 AND 9007199254740991), maximum_fee_and_rent_lamports INTEGER NOT NULL CHECK(typeof(maximum_fee_and_rent_lamports)='integer' AND maximum_fee_and_rent_lamports BETWEEN 0 AND 9007199254740991),state TEXT NOT NULL DEFAULT 'open' CHECK(state IN ('open','paused','stopped')),revision INTEGER NOT NULL DEFAULT 0,
 expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 CHECK(maximum_input_lamports+maximum_fee_and_rent_lamports<=9007199254740991),PRIMARY KEY(owner_id,id));
--> statement-breakpoint
CREATE UNIQUE INDEX auto_buy_budget_id ON auto_buy_budgets(id);
--> statement-breakpoint
CREATE TABLE auto_buy_budget_claims (
 owner_id TEXT NOT NULL,id TEXT NOT NULL,session_id TEXT NOT NULL,strategy_id TEXT NOT NULL,wallet TEXT NOT NULL,wallet_revision INTEGER NOT NULL,
 candidate_key TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('ExactIn','ExactOut')),source_sha256 TEXT NOT NULL,packet_sha256 TEXT NOT NULL,
 minimum_output_token_raw TEXT NOT NULL,maximum_input_lamports INTEGER NOT NULL CHECK(typeof(maximum_input_lamports)='integer' AND maximum_input_lamports BETWEEN 1 AND 9007199254740991), maximum_fee_and_rent_lamports INTEGER NOT NULL CHECK(typeof(maximum_fee_and_rent_lamports)='integer' AND maximum_fee_and_rent_lamports BETWEEN 0 AND 9007199254740991),document TEXT NOT NULL CHECK(json_valid(document) AND length(CAST(document AS BLOB))<=8192),document_sha256 TEXT NOT NULL,
 state TEXT NOT NULL DEFAULT 'held' CHECK(state IN ('held','uncertain','released')),expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 CHECK(maximum_input_lamports+maximum_fee_and_rent_lamports<=9007199254740991),PRIMARY KEY(owner_id,id),FOREIGN KEY(owner_id,session_id) REFERENCES auto_buy_budgets(owner_id,id));
