CREATE TRIGGER auto_buy_budget_insert BEFORE INSERT ON auto_buy_budgets BEGIN
 SELECT RAISE(ABORT,'Exact disabled budget terms required') WHERE EXISTS(SELECT 1 FROM auto_buy_budgets WHERE id=NEW.id) OR NEW.state!='open' OR NEW.revision!=0 OR length(NEW.owner_id) NOT BETWEEN 1 AND 256
 OR NEW.created_at IS NOT strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NEW.updated_at IS NOT NEW.created_at OR NOT (typeof(NEW.document_sha256)='text' AND length(NEW.document_sha256)=64 AND NEW.document_sha256 NOT GLOB '*[^a-f0-9]*')
 OR json_extract(NEW.document,'$.inputMint') IS NOT 'So11111111111111111111111111111111111111112' OR json_extract(NEW.document,'$.terms.mint') IS 'So11111111111111111111111111111111111111112' OR json_type(NEW.document,'$.terms.projectRevision') IS NOT 'integer' OR json_extract(NEW.document,'$.format') IS NOT 'auto-buy-budget-v1' OR NOT (json_type(NEW.document,'$.signingAllowed') IS 'false' AND json_type(NEW.document,'$.executionAllowed') IS 'false' AND json_type(NEW.document,'$.automaticExecutionAllowed') IS 'false' AND json_type(NEW.document,'$.sourceVerified') IS 'false' AND json_type(NEW.document,'$.walletFundsReserved') IS 'false' AND json_type(NEW.document,'$.instructionsVerified') IS 'false')
 OR json_extract(NEW.document,'$.terms.id') IS NOT NEW.id OR json_extract(NEW.document,'$.terms.projectId') IS NOT NEW.project_id
 OR json_extract(NEW.document,'$.terms.projectRevision') IS NOT NEW.project_revision OR typeof(NEW.project_revision)!='integer' OR NEW.project_revision NOT BETWEEN 1 AND 1000000000 OR json_type(NEW.document,'$.terms.tokenDecimals') IS NOT 'integer' OR json_extract(NEW.document,'$.terms.tokenDecimals') NOT BETWEEN 0 AND 255
 OR NOT ((typeof(json_extract(json_extract(NEW.document,'$.terms'),'$.maximumInputLamports'))='text' AND length(json_extract(json_extract(NEW.document,'$.terms'),'$.maximumInputLamports')) BETWEEN 1 AND 16 AND json_extract(json_extract(NEW.document,'$.terms'),'$.maximumInputLamports') NOT GLOB '*[^0-9]*' AND (json_extract(json_extract(NEW.document,'$.terms'),'$.maximumInputLamports')='0' OR substr(json_extract(json_extract(NEW.document,'$.terms'),'$.maximumInputLamports'),1,1)!='0') AND CAST(json_extract(json_extract(NEW.document,'$.terms'),'$.maximumInputLamports') AS INTEGER) BETWEEN 1 AND 9007199254740991) AND (typeof(json_extract(json_extract(NEW.document,'$.terms'),'$.maximumFeeAndRentLamports'))='text' AND length(json_extract(json_extract(NEW.document,'$.terms'),'$.maximumFeeAndRentLamports')) BETWEEN 1 AND 16 AND json_extract(json_extract(NEW.document,'$.terms'),'$.maximumFeeAndRentLamports') NOT GLOB '*[^0-9]*' AND (json_extract(json_extract(NEW.document,'$.terms'),'$.maximumFeeAndRentLamports')='0' OR substr(json_extract(json_extract(NEW.document,'$.terms'),'$.maximumFeeAndRentLamports'),1,1)!='0') AND CAST(json_extract(json_extract(NEW.document,'$.terms'),'$.maximumFeeAndRentLamports') AS INTEGER) BETWEEN 0 AND 9007199254740991))
 OR json_extract(NEW.document,'$.terms.maximumInputLamports') IS NOT CAST(NEW.maximum_input_lamports AS TEXT)
 OR json_extract(NEW.document,'$.terms.maximumFeeAndRentLamports') IS NOT CAST(NEW.maximum_fee_and_rent_lamports AS TEXT)
 OR json_extract(NEW.document,'$.terms.expiresAt') IS NOT NEW.expires_at OR NEW.expires_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now')
 OR NEW.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now','+31 days') OR NEW.expires_at IS NOT strftime('%Y-%m-%dT%H:%M:%fZ',NEW.expires_at)
 OR json_type(NEW.document,'$.terms.wallets') IS NOT 'array' OR json_array_length(NEW.document,'$.terms.wallets') NOT BETWEEN 1 AND 25
 OR json_type(NEW.document,'$.terms.strategies') IS NOT 'array' OR json_array_length(NEW.document,'$.terms.strategies') NOT BETWEEN 1 AND 8
 OR (SELECT count(DISTINCT json_extract(value,'$.address')) FROM json_each(NEW.document,'$.terms.wallets'))!=json_array_length(NEW.document,'$.terms.wallets')
 OR (SELECT count(DISTINCT json_extract(value,'$.id')) FROM json_each(NEW.document,'$.terms.strategies'))!=json_array_length(NEW.document,'$.terms.strategies')
 OR EXISTS(SELECT 1 FROM json_each(NEW.document,'$.terms.wallets') w WHERE NOT ((typeof(json_extract(w.value,'$.maximumInputLamports'))='text' AND length(json_extract(w.value,'$.maximumInputLamports')) BETWEEN 1 AND 16 AND json_extract(w.value,'$.maximumInputLamports') NOT GLOB '*[^0-9]*' AND (json_extract(w.value,'$.maximumInputLamports')='0' OR substr(json_extract(w.value,'$.maximumInputLamports'),1,1)!='0') AND CAST(json_extract(w.value,'$.maximumInputLamports') AS INTEGER) BETWEEN 1 AND 9007199254740991) AND (typeof(json_extract(w.value,'$.maximumFeeAndRentLamports'))='text' AND length(json_extract(w.value,'$.maximumFeeAndRentLamports')) BETWEEN 1 AND 16 AND json_extract(w.value,'$.maximumFeeAndRentLamports') NOT GLOB '*[^0-9]*' AND (json_extract(w.value,'$.maximumFeeAndRentLamports')='0' OR substr(json_extract(w.value,'$.maximumFeeAndRentLamports'),1,1)!='0') AND CAST(json_extract(w.value,'$.maximumFeeAndRentLamports') AS INTEGER) BETWEEN 0 AND 9007199254740991)) OR json_type(w.value,'$.revision') IS NOT 'integer' OR json_extract(w.value,'$.revision') NOT BETWEEN 1 AND 1000000000
 OR CAST(json_extract(w.value,'$.maximumInputLamports') AS INTEGER)>NEW.maximum_input_lamports OR CAST(json_extract(w.value,'$.maximumFeeAndRentLamports') AS INTEGER)>NEW.maximum_fee_and_rent_lamports)
 OR EXISTS(SELECT 1 FROM json_each(NEW.document,'$.terms.strategies') s WHERE NOT ((typeof(json_extract(s.value,'$.maximumInputLamports'))='text' AND length(json_extract(s.value,'$.maximumInputLamports')) BETWEEN 1 AND 16 AND json_extract(s.value,'$.maximumInputLamports') NOT GLOB '*[^0-9]*' AND (json_extract(s.value,'$.maximumInputLamports')='0' OR substr(json_extract(s.value,'$.maximumInputLamports'),1,1)!='0') AND CAST(json_extract(s.value,'$.maximumInputLamports') AS INTEGER) BETWEEN 1 AND 9007199254740991) AND (typeof(json_extract(s.value,'$.maximumFeeAndRentLamports'))='text' AND length(json_extract(s.value,'$.maximumFeeAndRentLamports')) BETWEEN 1 AND 16 AND json_extract(s.value,'$.maximumFeeAndRentLamports') NOT GLOB '*[^0-9]*' AND (json_extract(s.value,'$.maximumFeeAndRentLamports')='0' OR substr(json_extract(s.value,'$.maximumFeeAndRentLamports'),1,1)!='0') AND CAST(json_extract(s.value,'$.maximumFeeAndRentLamports') AS INTEGER) BETWEEN 0 AND 9007199254740991)) OR json_type(s.value,'$.kind') IS NOT 'text' OR json_extract(s.value,'$.kind') NOT IN ('Counter','DCA','Limit') OR NOT (typeof(json_extract(s.value,'$.sourceSha256'))='text' AND length(json_extract(s.value,'$.sourceSha256'))=64 AND json_extract(s.value,'$.sourceSha256') NOT GLOB '*[^a-f0-9]*')
 OR CAST(json_extract(s.value,'$.maximumInputLamports') AS INTEGER)>NEW.maximum_input_lamports OR CAST(json_extract(s.value,'$.maximumFeeAndRentLamports') AS INTEGER)>NEW.maximum_fee_and_rent_lamports);
 SELECT RAISE(ABORT,'Current owned budget context required') WHERE NOT (EXISTS(SELECT 1 FROM imported_token_projects p WHERE p.owner_id=NEW.owner_id AND p.id=NEW.project_id AND p.revision=NEW.project_revision AND p.archived=0 AND p.chain='Solana' AND json_extract(p.document,'$.token.chain')='Solana' AND json_extract(p.document,'$.token.address')=p.address AND p.address=json_extract(NEW.document,'$.terms.mint') AND p.document=json_extract(NEW.document,'$.projectDocument') AND json_extract(p.document,'$.token.decimals')=json_extract(NEW.document,'$.terms.tokenDecimals')) AND NOT EXISTS(SELECT 1 FROM json_each(NEW.document,'$.terms.wallets') r WHERE NOT EXISTS(SELECT 1 FROM workspace_wallets w JOIN wallet_ownership_proofs o ON o.owner_id=w.owner_id AND o.chain=w.chain AND o.address=w.address WHERE w.owner_id=NEW.owner_id AND w.chain='Solana' AND w.address=json_extract(r.value,'$.address') AND w.revision=json_extract(r.value,'$.revision') AND w.archived=0)));
END;
