CREATE TRIGGER auto_buy_budget_claim_insert BEFORE INSERT ON auto_buy_budget_claims BEGIN
 SELECT RAISE(ABORT,'Exact disabled candidate budget required') WHERE EXISTS(SELECT 1 FROM auto_buy_budget_claims WHERE id=NEW.id) OR EXISTS(SELECT 1 FROM auto_buy_budget_claims c WHERE c.owner_id=NEW.owner_id AND c.state!='released' AND (c.packet_sha256=NEW.packet_sha256 OR (c.session_id=NEW.session_id AND c.strategy_id=NEW.strategy_id AND c.candidate_key=NEW.candidate_key))) OR (NEW.kind='ExactOut' AND EXISTS(SELECT 1 FROM auto_buy_budget_claims c WHERE c.owner_id=NEW.owner_id AND c.kind='ExactOut' AND c.state!='released' AND c.source_sha256=NEW.source_sha256 AND c.candidate_key=NEW.candidate_key)) OR NEW.state!='held' OR NEW.created_at IS NOT strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NEW.updated_at IS NOT NEW.created_at
 OR NOT (typeof(NEW.document_sha256)='text' AND length(NEW.document_sha256)=64 AND NEW.document_sha256 NOT GLOB '*[^a-f0-9]*') OR NOT (typeof(NEW.packet_sha256)='text' AND length(NEW.packet_sha256)=64 AND NEW.packet_sha256 NOT GLOB '*[^a-f0-9]*') OR NOT (typeof(NEW.source_sha256)='text' AND length(NEW.source_sha256)=64 AND NEW.source_sha256 NOT GLOB '*[^a-f0-9]*')
 OR json_extract(NEW.document,'$.inputMint') IS NOT 'So11111111111111111111111111111111111111112' OR json_extract(NEW.document,'$.format') IS NOT 'auto-buy-budget-claim-v1' OR NOT (json_type(NEW.document,'$.signingAllowed') IS 'false' AND json_type(NEW.document,'$.executionAllowed') IS 'false' AND json_type(NEW.document,'$.automaticExecutionAllowed') IS 'false' AND json_type(NEW.document,'$.sourceVerified') IS 'false' AND json_type(NEW.document,'$.walletFundsReserved') IS 'false' AND json_type(NEW.document,'$.instructionsVerified') IS 'false')
 OR json_type(NEW.document,'$.request.sessionRevision') IS NOT 'integer' OR json_extract(NEW.document,'$.request.sessionRevision') NOT BETWEEN 0 AND 1000000000 OR NEW.expires_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NEW.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now','+30 seconds') OR NEW.expires_at IS NOT strftime('%Y-%m-%dT%H:%M:%fZ',NEW.expires_at)
 OR typeof(NEW.minimum_output_token_raw)!='text' OR length(NEW.minimum_output_token_raw) NOT BETWEEN 1 AND 20 OR NEW.minimum_output_token_raw GLOB '*[^0-9]*' OR substr(NEW.minimum_output_token_raw,1,1)='0'
 OR (length(NEW.minimum_output_token_raw)=20 AND NEW.minimum_output_token_raw>'18446744073709551615');
 SELECT RAISE(ABORT,'Candidate identity differs') WHERE json_type(NEW.document,'$.request.id') IS NOT 'text' OR json_type(NEW.document,'$.request.sessionId') IS NOT 'text' OR json_type(NEW.document,'$.request.strategyId') IS NOT 'text' OR json_type(NEW.document,'$.request.wallet') IS NOT 'text' OR json_type(NEW.document,'$.request.candidateKey') IS NOT 'text' OR json_type(NEW.document,'$.request.kind') IS NOT 'text' OR json_type(NEW.document,'$.request.sourceSha256') IS NOT 'text' OR json_type(NEW.document,'$.request.packetSha256') IS NOT 'text' OR json_type(NEW.document,'$.request.minimumOutputTokenRaw') IS NOT 'text' OR json_type(NEW.document,'$.request.expiresAt') IS NOT 'text' OR json_type(NEW.document,'$.request.maximumInputLamports') IS NOT 'text' OR json_type(NEW.document,'$.request.maximumFeeAndRentLamports') IS NOT 'text' OR json_type(NEW.document,'$.request.walletRevision') IS NOT 'integer' OR
 json_extract(NEW.document,'$.request.id') IS NOT NEW.id OR json_extract(NEW.document,'$.request.sessionId') IS NOT NEW.session_id OR json_extract(NEW.document,'$.request.strategyId') IS NOT NEW.strategy_id OR json_extract(NEW.document,'$.request.wallet') IS NOT NEW.wallet OR json_extract(NEW.document,'$.request.walletRevision') IS NOT NEW.wallet_revision OR json_extract(NEW.document,'$.request.candidateKey') IS NOT NEW.candidate_key OR json_extract(NEW.document,'$.request.kind') IS NOT NEW.kind OR json_extract(NEW.document,'$.request.sourceSha256') IS NOT NEW.source_sha256 OR json_extract(NEW.document,'$.request.packetSha256') IS NOT NEW.packet_sha256 OR json_extract(NEW.document,'$.request.minimumOutputTokenRaw') IS NOT NEW.minimum_output_token_raw OR json_extract(NEW.document,'$.request.expiresAt') IS NOT NEW.expires_at
 OR json_extract(NEW.document,'$.request.maximumInputLamports') IS NOT CAST(NEW.maximum_input_lamports AS TEXT)
 OR json_extract(NEW.document,'$.request.maximumFeeAndRentLamports') IS NOT CAST(NEW.maximum_fee_and_rent_lamports AS TEXT);
 SELECT RAISE(ABORT,'Budget closed, stale, or capacity unavailable') WHERE NOT EXISTS(
 SELECT 1 FROM auto_buy_budgets b,json_each(b.document,'$.terms.wallets') w,json_each(b.document,'$.terms.strategies') s
 WHERE b.owner_id=NEW.owner_id AND b.id=NEW.session_id AND b.state='open' AND b.revision=json_extract(NEW.document,'$.request.sessionRevision') AND b.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND NEW.expires_at<=b.expires_at
 AND EXISTS(SELECT 1 FROM imported_token_projects p WHERE p.owner_id=b.owner_id AND p.id=b.project_id AND p.revision=b.project_revision AND p.archived=0 AND p.chain='Solana' AND json_extract(p.document,'$.token.chain')='Solana' AND json_extract(p.document,'$.token.address')=p.address AND p.address=json_extract(b.document,'$.terms.mint') AND p.document=json_extract(b.document,'$.projectDocument') AND json_extract(p.document,'$.token.decimals')=json_extract(b.document,'$.terms.tokenDecimals')) AND NOT EXISTS(SELECT 1 FROM json_each(b.document,'$.terms.wallets') r WHERE NOT EXISTS(SELECT 1 FROM workspace_wallets w JOIN wallet_ownership_proofs o ON o.owner_id=w.owner_id AND o.chain=w.chain AND o.address=w.address WHERE w.owner_id=b.owner_id AND w.chain='Solana' AND w.address=json_extract(r.value,'$.address') AND w.revision=json_extract(r.value,'$.revision') AND w.archived=0))
 AND json_extract(w.value,'$.address')=NEW.wallet AND json_extract(w.value,'$.revision')=NEW.wallet_revision
 AND json_extract(s.value,'$.id')=NEW.strategy_id AND json_extract(s.value,'$.sourceSha256')=NEW.source_sha256
 AND ((json_extract(s.value,'$.kind')='Counter' AND NEW.kind='ExactOut' AND (typeof(NEW.candidate_key)='text' AND length(NEW.candidate_key)=64 AND NEW.candidate_key NOT GLOB '*[^a-f0-9]*'))
 OR (json_extract(s.value,'$.kind')='DCA' AND NEW.kind='ExactIn' AND length(NEW.candidate_key) BETWEEN 1 AND 10 AND NEW.candidate_key NOT GLOB '*[^0-9]*' AND CAST(CAST(NEW.candidate_key AS INTEGER) AS TEXT)=NEW.candidate_key AND CAST(NEW.candidate_key AS INTEGER)<=1000000000)
 OR (json_extract(s.value,'$.kind')='Limit' AND NEW.kind='ExactIn' AND NEW.candidate_key='once'))
 AND NEW.maximum_input_lamports+COALESCE((SELECT SUM(c.maximum_input_lamports) FROM auto_buy_budget_claims c WHERE c.owner_id=b.owner_id AND c.session_id=b.id AND c.state!='released'),0)<=b.maximum_input_lamports
 AND NEW.maximum_fee_and_rent_lamports+COALESCE((SELECT SUM(c.maximum_fee_and_rent_lamports) FROM auto_buy_budget_claims c WHERE c.owner_id=b.owner_id AND c.session_id=b.id AND c.state!='released'),0)<=b.maximum_fee_and_rent_lamports
 AND NEW.maximum_input_lamports+COALESCE((SELECT SUM(c.maximum_input_lamports) FROM auto_buy_budget_claims c WHERE c.owner_id=b.owner_id AND c.session_id=b.id AND c.wallet=NEW.wallet AND c.state!='released'),0)<=CAST(json_extract(w.value,'$.maximumInputLamports') AS INTEGER) AND NEW.maximum_fee_and_rent_lamports+COALESCE((SELECT SUM(c.maximum_fee_and_rent_lamports) FROM auto_buy_budget_claims c WHERE c.owner_id=b.owner_id AND c.session_id=b.id AND c.wallet=NEW.wallet AND c.state!='released'),0)<=CAST(json_extract(w.value,'$.maximumFeeAndRentLamports') AS INTEGER) AND NEW.maximum_input_lamports+COALESCE((SELECT SUM(c.maximum_input_lamports) FROM auto_buy_budget_claims c WHERE c.owner_id=b.owner_id AND c.session_id=b.id AND c.strategy_id=NEW.strategy_id AND c.state!='released'),0)<=CAST(json_extract(s.value,'$.maximumInputLamports') AS INTEGER) AND NEW.maximum_fee_and_rent_lamports+COALESCE((SELECT SUM(c.maximum_fee_and_rent_lamports) FROM auto_buy_budget_claims c WHERE c.owner_id=b.owner_id AND c.session_id=b.id AND c.strategy_id=NEW.strategy_id AND c.state!='released'),0)<=CAST(json_extract(s.value,'$.maximumFeeAndRentLamports') AS INTEGER)
 );
 SELECT RAISE(ABORT,'Signing evidence already exists') WHERE EXISTS(SELECT 1 FROM imported_swap_signing_intents i WHERE i.owner_id=NEW.owner_id AND (i.preparation_id=NEW.id OR i.id=NEW.id OR json_extract(i.document,'$.sha256')=NEW.packet_sha256)) OR EXISTS(SELECT 1 FROM warmup_signing_intents i WHERE i.owner_id=NEW.owner_id AND (i.preparation_id=NEW.id OR i.id=NEW.id OR json_extract(i.document,'$.sha256')=NEW.packet_sha256));
