CREATE TRIGGER auto_buy_budgets_update BEFORE UPDATE ON auto_buy_budgets BEGIN SELECT RAISE(ABORT,'Immutable budget identity or invalid transition') WHERE NEW.owner_id IS NOT OLD.owner_id OR NEW.id IS NOT OLD.id OR NEW.project_id IS NOT OLD.project_id OR NEW.project_revision IS NOT OLD.project_revision OR NEW.document IS NOT OLD.document OR NEW.document_sha256 IS NOT OLD.document_sha256 OR NEW.maximum_input_lamports IS NOT OLD.maximum_input_lamports OR NEW.maximum_fee_and_rent_lamports IS NOT OLD.maximum_fee_and_rent_lamports OR NEW.expires_at IS NOT OLD.expires_at OR NEW.created_at IS NOT OLD.created_at OR NEW.updated_at IS NOT strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NEW.updated_at<OLD.updated_at OR NEW.revision!=OLD.revision+1 OR NOT ((OLD.state='open' AND NEW.state IN ('paused','stopped')) OR (OLD.state='paused' AND NEW.state IN ('open','stopped'))) OR (NEW.state!='stopped' AND OLD.expires_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
